<!doctype html><html <?php language_attributes(); ?> class="ccs-app-document"><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#000A52"><meta name="robots" content="noindex,nofollow"><title>Acesso · CCShalom Escalas</title><?php wp_head(); ?></head><body class="ccs-standalone ccs-access-page"><div id="ccs-app"><main class="ccs-access"><section class="ccs-access-brand"><div class="ccs-access-brand-inner"><?php if (get_option('ccs_logo')) { ?><img class="ccs-access-logo" src="<?php echo esc_url(get_option('ccs_logo')); ?>" alt="CCShalom"><?php } else { ?><span class="ccs-wordmark">CCShalom</span><?php } ?><span class="ccs-access-tag">ESCALAS</span><div class="ccs-access-intro"><span class="ccs-eyebrow">JUNTOS PARA SERVIR</span><h1><span class="ccs-access-mobile-title">Juntos para servir.</span><span class="ccs-access-desktop-title">Seu lugar.<br>Sua equipe.<br>Nosso propósito.</span></h1><p>Organize sua participação e faça parte das próximas celebrações.</p></div><p class="ccs-access-motto">COMUNHÃO · DISCIPULADO · MISSÃO</p></div></section><section class="ccs-access-form"><div class="ccs-access-form-inner"><span class="ccs-eyebrow">BEM-VINDO À EQUIPE</span><h2><?php echo $screen==='login'?'Vamos servir juntos?':($screen==='forgot'?'Recuperar acesso':'Sua nova senha'); ?></h2><p><?php echo $screen==='login'?'Entre para acompanhar suas equipes e escalas.':($screen==='forgot'?'Informe seu e-mail para receber o link de recuperação.':'Escolha uma senha para voltar às suas escalas.'); ?></p>
<?php if (isset($_GET['ccs_registered'])) { ?><p class="ccs-account-notice">Cadastro realizado! Entre com seu e-mail e senha.</p><?php } ?>
<?php if (isset($_GET['reset'])) { ?><p class="ccs-account-notice">Senha atualizada. Entre novamente. Os acessos por biometria anteriores foram removidos e podem ser cadastrados no perfil.</p><?php } ?>
<?php if (isset($_GET['sent'])) { ?><p class="ccs-account-notice">Se o e-mail estiver cadastrado, você receberá as instruções de recuperação.</p><?php } ?>
<div class="ccs-form-error" role="alert" id="ccs-auth-error"><?php echo esc_html($error); ?></div>
<?php if ($screen==='login') { ?><button type="button" class="ccs-button ccs-biometric-button" data-passkey-login disabled><span aria-hidden="true">◎</span> Entrar com biometria</button><p class="ccs-hint" id="ccs-biometric-hint">Use um acesso já ativado no seu perfil.</p><div class="ccs-divider"><span>ou entre com sua senha</span></div><?php } ?>
<form method="post" action="<?php echo esc_url(CCS::auth_url($screen)); ?>" data-auth-form><input type="hidden" name="ccs_event" value="<?php echo absint($_POST['ccs_event']??$_GET['ccs_event']??0); ?>"><input type="hidden" name="action" value="ccs_auth"><input type="hidden" name="screen" value="<?php echo esc_attr($screen); ?>"><input type="hidden" name="binding" value="<?php echo esc_attr(CCS::auth_binding()); ?>"><?php wp_nonce_field('ccs_auth'); ?>
<?php if ($screen==='reset') { ?><input type="hidden" name="key" value="<?php echo esc_attr(wp_unslash($_POST['key']??$_GET['key']??'')); ?>"><input type="hidden" name="login" value="<?php echo esc_attr(wp_unslash($_POST['login']??$_GET['login']??'')); ?>"><?php } else { ?><label class="ccs-field">E-mail ou usuário<input name="login" autocomplete="username webauthn" autocapitalize="none" spellcheck="false" required></label><?php } ?>
<?php if ($screen!=='forgot') { ?><label class="ccs-field">Senha<div class="ccs-password-wrap"><input id="ccs-password" type="password" name="password" autocomplete="<?php echo $screen==='reset'?'new-password':'current-password'; ?>" <?php echo $screen==='reset'?'minlength="12" maxlength="128"':''; ?> required><button type="button" data-toggle-password aria-label="Mostrar senha" aria-pressed="false">Mostrar</button></div></label><?php } ?>
<?php if ($screen==='login') { ?><div class="ccs-login-options"><label class="ccs-check"><input type="checkbox" name="remember" value="1" checked> Manter conectado</label><a href="<?php echo esc_url(CCS::auth_url('forgot')); ?>">Esqueci minha senha</a></div><?php } ?>
<button type="submit" class="ccs-button ccs-submit-wide"><?php echo $screen==='login'?'Entrar na minha conta':($screen==='forgot'?'Enviar link de recuperação':'Salvar nova senha'); ?></button></form>
<p class="ccs-access-bottom"><?php if ($screen==='login') { ?>Ainda não tem conta? <a href="<?php echo esc_url(CCS::signup_url()); ?>">Cadastre-se</a><?php } else { ?><a href="<?php echo esc_url(CCS::auth_url()); ?>">Voltar para o login</a><?php } ?></p><p class="ccs-access-footer">CCShalom · Cada pessoa faz parte.</p></div></section></main></div><?php wp_footer(); ?></body></html>

